    flag = ancilla_qubits[0]

    # Eight bit patterns that satisfy the vertex‑cover constraints
    # (order corresponds to problem_qubits: [q0, q1, q2, q3, q4])
    patterns = [
        [1, 0, 0, 0, 1],  # {0,4}
        [0, 1, 0, 0, 1],  # {1,4}
        [1, 1, 0, 0, 1],  # {0,1,4}
