from qiskit import QuantumCircuit

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int], ancilla_qubits: list[int]) -> None:
    """
    Oracle for the 5‑vertex vertex‑cover problem with size <= 2.
    Marks the two valid basis states |01100> and |01010> with a phase flip.
    """
    # Phase register: first ancilla qubit
    phase_ancilla = ancilla_qubits[0]
    # Ancillas needed for the 5‑controlled X decomposition
    mct_ancillas = ancilla_qubits[5:]       # three ancillas (indices 5,6,7)

    # Helper: apply a phase flip when problem_qubits matches a given pattern
    def apply_phase_for_pattern(pattern_bits: list[int]) -> None:
        # --- compute: set phase_ancilla to 1 iff problem_qubits == pattern_bits
        for idx, bit in enumerate(pattern_bits):
            if bit == 0:          # flip control qubits marked 0
                qc.x(problem_qubits[idx])

        qc.mcx(problem_qubits, phase_ancilla, ancilla_qubits=mct_ancillas)

        for idx, bit in enumerate(pattern_bits):
            if bit == 0:          # restore flipped control qubits
                qc.x(problem_qubits[idx])

        # --- phase
        qc.z(phase_ancilla)

        # --- uncompute: reverse the compute part
        for idx, bit in enumerate(pattern_bits):
            if bit == 0:
                qc.x(problem_qubits[idx])

        qc.mcx(problem_qubits, phase_ancilla, ancilla_qubits=mct_ancillas)

        for idx, bit in enumerate(pattern_bits):
            if bit == 0:
                qc.x(problem_qubits[idx])

    # Two valid vertex‑cover configurations (vertex indices start at 0)
    # 01100 -> vertices {1,2}
    # 01010 -> vertices {1,3}
    valid_patterns = [
        [0, 1, 1, 0, 0],
        [0, 1, 0, 1, 0],
    ]

    # Apply the oracle for each valid pattern
    for pat in valid_patterns:
        apply_phase_for_pattern(pat)
